B.axw=new A.dg("Qalqalah (echo)","The letters qaaf, taa, baa, jeem and daal with sukoon are pronounced with a light bounce.","Let the letter bounce slightly without adding a vowel.")
B.aeV=new A.Z(B.bX,[B.axp,B.axw],t.nb)
B.axc=new A.dg("\u0627\u0644\u0645\u062f \u0627\u0644\u0637\u0628\u064a\u0639\u064a","\u062d\u0631\u0648\u0641 \u0627\u0644\u0645\u062f (\u0627 \u0648 \u064a) \u062a\u064f\u0645\u062f \u0628\u0645\u0642\u062f\u0627\u0631 \u062d\u0631\u0643\u062a\u064a\u0646.","\u0645\u062f\u0651 \u0627\u0644\u0635\u0648\u062a \u062d\u0631\u0643\u062a\u064a\u0646 \u0641\u0642\u0637\u060c \u0644\u0627 \u0623\u0642\u0644 \u0648\u0644\u0627 \u0623\u0643\u062b\u0631.")
B.axb=new A.dg("Natural madd","The madd letters alif, waw and yaa are lengthened for two counts.","Stretch the sound for exactly two counts.")
B.aeY=new A.Z(B.bX,[B.axc,B.axb],t.nb)
B.ax9=new A.dg("\u0627\u0644\u0645\u062f \u0627\u0644\u062c\u0627\u0626\u0632","\u0645\u062f\u064c\u0651 \u064a\u062c\u0648\u0632 \u0641\u064a\u0647 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0645\u0642\u062f\u0627\u0631 \u062d\u0633\u0628 \u0646\u0648\u0639\u0647\u060c \u0645\u062b\u0644 \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0648\u0627\u0644\u0639\u0627\u0631\u0636 \u0644\u0644\u0633\u0643\u0648\u0646.","\u0627\u0644\u062a\u0632\u0645 \u0645\u0642\u062f\u0627\u0631\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0641\u064a \u062a\u0644\u0627\u0648\u062a\u0643 \u0643\u0644\u0647\u0627\u060c \u0643\u0645\u0627 \u062a\u0633\u0645\u0639\u0647 \u0645\u0646 \u0627\u0644\u0642\u0627\u0631\u0626.")
B.axo=new A.dg("Permissible madd","A madd that may be lengthened by more than one amount depending on its type, such as munfasil or aarid.","Keep one length throughout your recitation, as you hear from the reciter.")
B.aeS=new A.Z(B.bX,[B.ax9,B.axo],t.nb)
B.ax6=new A.dg("\u0627\u0644\u0645\u062f \u0627\u0644\u0648\u0627\u062c\u0628 \u0627\u0644\u0645\u062a\u0635\u0644","\u062d\u0631\u0641 \u0645\u062f \u0628\u0639\u062f\u0647 \u0647\u0645\u0632\u0629 \u0641\u064a \u0627\u0644\u0643\u0644\u0645\u0629 \u0646\u0641\u0633\u0647\u0627\u060c \u0648\u064a\u064f\u0645\u062f \u0623\u0631\u0628\u0639 \u0623\u0648 \u062e\u0645\u0633 \u062d\u0631\u0643\u0627\u062a.","\u0644\u0627 \u062a\u0642\u0635\u0631 \u0647\u0630\u0627 \u0627\u0644\u0645\u062f\u061b \u0623\u0637\u0650\u0644\u0647 \u0642\u0628\u0644 \u0646\u0637\u0642 \u0627\u0644\u0647\u0645\u0632\u0629.")
B.axr=new A.dg("Obligatory madd (muttasil)","A madd letter followed by hamza in the same word, lengthened for four or five counts.","Don't shorten it; stretch it before saying the hamza.")
B.af1=new A.Z(B.bX,[B.ax6,B.axr],t.nb)
